      "instances": "max",
      "domain": "api.example.com",
      "sslEmail": "admin@example.com"
    },
    "staging": {
      "server": "ubuntu@staging.example.com",
      "port": 3000,
      "instances": 2,
      "sslEmail": "admin@example.com",
      "domain": ["domain1.example.com", "domain2.example.com"]
    }
  },
  "build": {
    "command": "npm run build",
    "directory": "dist",
